/**
 * Safe-by-default HTML tagged template literal. Zero dependencies.
 *
 * - `html`<div>${userInput}</div>`` escapes every interpolated plain value
 *   (& < > " '), leaving static template parts untouched.
 * - Arrays of html results are flattened and joined with '' (no separators).
 * - Values already produced by `html` (or wrapped by `raw`) pass through
 *   without double-escaping.
 * - The result is an HtmlValue object (with toString / toJSON), not a bare
 *   string, so nesting is detectable via instanceof / isHtml().
 */

const ESCAPES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

const ESCAPE_RE = /[&<>"']/g;

/** Escape a plain value for safe interpolation in HTML text or attribute position. */
function escape(value) {
  return String(value).replace(ESCAPE_RE, (ch) => ESCAPES[ch]);
}

/** Marker so nesting is detectable even across realms/iframes. */
const BRAND = Symbol.for('htmltag.html');

export class HtmlValue {
  #html;

  constructor(htmlString) {
    this.#html = String(htmlString);
  }

  /** The trusted, already-escaped markup. */
  toString() {
    return this.#html;
  }

  [Symbol.toPrimitive](hint) {
    if (hint === 'number') return NaN;
    return this.#html;
  }

  toJSON() {
    return this.#html;
  }

  get [BRAND]() {
    return true;
  }
}

/** True if the value was produced by `html` or wrapped by `raw`. */
export function isHtml(value) {
  return (
    value instanceof HtmlValue ||
    (value !== null && typeof value === 'object' && Boolean(value[BRAND]))
  );
}

/**
 * Interpolate a single dynamic value into trusted markup:
 * html/raw results pass through as-is, arrays flatten recursively,
 * anything else gets escaped exactly once.
 */
function interpolate(value) {
  if (isHtml(value)) {
    // Already escaped — reuse its exact markup, never re-escape.
    return value.toString();
  }
  if (Array.isArray(value)) {
    let out = '';
    for (const item of value) out += interpolate(item);
    return out;
  }
  return escape(value);
}

/**
 * Tagged template literal for building HTML safely.
 *
 *   const page = html`<ul>${items.map((i) => html`<li>${i}</li>`)}</ul>`;
 */
export function html(strings, ...values) {
  let out = '';
  for (let i = 0; i < strings.length; i++) {
    out += strings[i];
    if (i < values.length) out += interpolate(values[i]);
  }
  return new HtmlValue(out);
}

/**
 * Mark a string as trusted, pre-escaped markup: it will pass through `html`
 * interpolation without being escaped again. Use only for content you control.
 */
export function raw(markup) {
  return new HtmlValue(markup);
}

