import { test } from 'node:test';
import assert from 'node:assert/strict';
import { html, raw, isHtml } from './index.mjs';

test('returns an object with toString, not a bare string', () => {
  const out = html`<p>hi</p>`;
  assert.equal(typeof out, 'object');
  assert.notEqual(typeof out, 'string');
  assert.equal(String(out), '<p>hi</p>');
  assert.equal(isHtml(out), true);
});

test('escapes script injection to inert markup', () => {
  const evil = '<script>alert(1)</script>';
  const out = String(html`<div>${evil}</div>`);
  assert.equal(
    out,
    '<div>&lt;script&gt;alert(1)&lt;/script&gt;</div>'
  );
  assert.ok(!out.includes('<script>'));
});

test('escapes all five dangerous characters', () => {
  const out = String(html`${`&<>"'`}`);
  assert.equal(out, '&amp;&lt;&gt;&quot;&#39;');
});

test('attribute-position quotes are escaped, breaking out is impossible', () => {
  const evil = '" onmouseover="alert(1)';
  const out = String(html`<a title="${evil}">x</a>`);
  assert.equal(
    out,
    '<a title="&quot; onmouseover=&quot;alert(1)">x</a>'
  );
  // Only one real attribute boundary pair remains.
  assert.match(out, /^<a title="[^"]*">x<\/a>$/);
});

test('static parts are left untouched', () => {
  const out = String(html`<b class="k">&nbsp; ${'v'} </b>`);
  assert.equal(out, '<b class="k">&nbsp; v </b>');
});

test('array of nested html items joins with no separator and no double-escaping', () => {
  const items = ['a & b', '<i>c</i>'];
  const list = html`<ul>${items.map((t) => html`<li>${t}</li>`)}</ul>`;
  assert.equal(
    String(list),
    '<ul><li>a &amp; b</li><li>&lt;i&gt;c&lt;/i&gt;</li></ul>'
  );
});

test('nested arrays flatten recursively', () => {
  const rows = [1, [2, 3]].map((n) =>
    Array.isArray(n)
      ? n.map((m) => html`<b>${m}</b>`)
      : html`<i>${n}</i>`
  );
  assert.equal(String(html`<p>${rows}</p>`), '<p><i>1</i><b>2</b><b>3</b></p>');
});

test('values produced by html pass through without double-escaping', () => {
  const inner = html`<em>${'<x>'}</em>`;
  const outer = html`<q>${inner}</q>`;
  assert.equal(String(outer), '<q><em>&lt;x&gt;</em></q>');
});

test('raw passthrough skips escaping', () => {
  const trusted = raw('<hr/>');
  assert.equal(String(html`<div>${trusted}</div>`), '<div><hr/></div>');
  assert.equal(isHtml(trusted), true);
});

test('double-escaping proven absent two levels deep', () => {
  const payload = '&'; // worst case: value that looks like an entity
  const level1 = html`<span>${payload}</span>`; // -> <span>&amp;</span>
  const level2 = html`<div>${level1}</div>`;
  const level3 = html`<section>${level2}</section>`;
  assert.equal(String(level1), '<span>&amp;</span>');
  assert.equal(String(level2), '<div><span>&amp;</span></div>');
  assert.equal(String(level3), '<section><div><span>&amp;</span></div></section>');
  assert.ok(!String(level3).includes('&amp;amp;'));
});

